content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --radius: 12px;
}

@media (prefers-color-scheme: dark) {
  :root {
    --primary-color: #6366f1;
    --primary-hover: #4f46e5;
    --bg-color: #0f172a;
    --card-bg: #1e293b;
    --text-main: #f8fafc;
    --text-muted: #94a3b8;
    --border-color: #334155;
    --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.3), 0 2px 4px -2px rgb(0 0 0 / 0.3);
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem 1rem;
}

.header {
  margin-bottom: 2rem;
  text-align: center;
}

.title {
  font-size: 2rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 0.5rem;
}

.subtitle {
  font-size: 1rem;
  color: var(--text-muted);
}

.main-content {
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.chart-card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 1.5rem;
  box-shadow: var(--shadow);
  border: 1px solid var(--border-color);
}

.summary-container {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 1.5rem;
}

.summary-card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 1.5rem;
  box-shadow: var(--shadow);
  border: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.summary-title {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.summary-value {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--primary-color);
}

.table-container {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 1.5rem;
  box-shadow: var(--shadow);
  border: 1px solid var(--border-color);
  overflow-x: auto;
}

.sales-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.95rem;
}

.sales-table th,
.sales-table td {
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--border-color);
}

.sales-table th {
  font-weight: 600;
  color: var(--text-muted);
  background-color: var(--border-color);
}

.sales-table tr:hover {
  background-color: var(--border-color);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
  font-weight: 500;
  border-radius: 6px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: background-color 0.2s, border-color 0.2s;
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

@media (max-width: 768px) {
  .app-container {
    padding: 1rem 0.5rem;
  }

  .title {
    font-size: 1.5rem;
  }

  .subtitle {
    font-size: 0.875rem;
  }

  .summary-container {
    grid-template-columns: 1fr;
    gap: 1rem;
  }

  .summary-card,
  .chart-card,
  .table-container {
    padding: 1rem;
  }

  .summary-value {
    font-size: 1.5rem;
  }
}

export type ID = string | number;

export interface BaseRecord {
  readonly id?: ID;
}

export interface MonthlySales extends BaseRecord {
  readonly month: string;
  readonly sales: number;
}

export type SalesDataset = readonly MonthlySales[];

export interface SalesChartProps {
  readonly data: SalesDataset;
}

export interface SummaryProps {
  readonly data: SalesDataset;
}

import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, CartesianGrid } from 'recharts';
import { SalesChartProps } from '../types';

export default function SalesChart({ data = [] }: SalesChartProps) {
  if (!data || data.length === 0) {
    return (
      <div className="chart-card">
        <h3 style={{ marginBottom: '1rem', fontSize: '1.25rem', fontWeight: 600 }}>月別売上推移</h3>
        <div style={{ width: '100%', height: 350, display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--text-muted)' }}>
          データがありません
        </div>
      </div>
    );
  }

  return (
    <div className="chart-card">
      <h3 style={{ marginBottom: '1rem', fontSize: '1.25rem', fontWeight: 600 }}>月別売上推移</h3>
      <div style={{ width: '100%', height: 350 }}>
        <ResponsiveContainer>
          <BarChart data={data} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
            <XAxis dataKey="month" stroke="#64748b" />
            <YAxis stroke="#64748b" />
            <Tooltip 
              formatter={(value: number | string) => [`${Number(value).toLocaleString()} 万円`, '売上']}
              contentStyle={{ backgroundColor: '#ffffff', borderRadius: '8px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
            />
            <Bar dataKey="sales" fill="var(--primary-color)" radius={[4, 4, 0, 0]} />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

import { SummaryProps, MonthlySales } from '../types';

export default function SalesSummary({ data = [] }: SummaryProps) {
  const totalSales = data.reduce((acc, curr) => acc + curr.sales, 0);
  const averageSales = data.length > 0 ? Math.round(totalSales / data.length) : 0;

  const getMaxSalesMonth = (): MonthlySales => {
    if (data.length === 0) return { month: '-', sales: 0 };
    return data.reduce((max, item) => (item.sales > max.sales ? item : max), data[0]);
  };

  const maxSalesItem: MonthlySales = getMaxSalesMonth();

  return (
    <div className="summary-container">
      <div className="summary-card">
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <span className="summary-title">年間合計売上</span>
          <svg width="20" height="20" fill="none" stroke="var(--primary-color)" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
        </div>
        <span className="summary-value">{totalSales.toLocaleString()} 万円</span>
      </div>
      <div className="summary-card">
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <span className="summary-title">月平均売上</span>
          <svg width="20" height="20" fill="none" stroke="var(--primary-color)" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" /></svg>
        </div>
        <span className="summary-value">{averageSales.toLocaleString()} 万円</span>
      </div>
      <div className="summary-card">
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <span className="summary-title">最高売上月</span>
          <svg width="20" height="20" fill="none" stroke="var(--primary-color)" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg>
        </div>
        <span className="summary-value">{maxSalesItem.month} ({maxSalesItem.sales.toLocaleString()} 万円)</span>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import SalesChart from './components/SalesChart';
import SalesSummary from './components/SalesSummary';
import { MonthlySales } from './types';

const initialData: MonthlySales[] = [
  { month: '1月', sales: 120 },
  { month: '2月', sales: 150 },
  { month: '3月', sales: 200 },
  { month: '4月', sales: 180 },
  { month: '5月', sales: 220 },
  { month: '6月', sales: 250 },
  { month: '7月', sales: 300 },
  { month: '8月', sales: 280 },
  { month: '9月', sales: 260 },
  { month: '10月', sales: 240 },
  { month: '11月', sales: 290 },
  { month: '12月', sales: 350 },
];

export default function App() {
  const [data, setData] = useState<MonthlySales[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [newMonth, setNewMonth] = useState<string>('');
  const [newSales, setNewSales] = useState<string>('');

  useEffect(() => {
    // APIからのデータ取得やローディング状態を想定した非同期処理
    const timer = setTimeout(() => {
      try {
        setData(initialData);
        setIsLoading(false);
      } catch (err) {
        setError('データの取得に失敗しました。');
        setIsLoading(false);
      }
    }, 400);

    return () => clearTimeout(timer);
  }, []);

  const handleAddSales = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMonth || !newSales) return;
    const salesNum = Number(newSales);
    if (isNaN(salesNum)) return;

    setData((prev) => [...prev, { month: newMonth, sales: salesNum }]);
    setNewMonth('');
    setNewSales('');
  };

  if (isLoading) {
    return (
      <div className="app-container" style={{ textAlign: 'center', padding: '4rem 0' }}>
        <p className="subtitle">データを読み込んでいます...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="app-container" style={{ textAlign: 'center', padding: '4rem 0', color: 'red' }}>
        <p>{error}</p>
      </div>
    );
  }

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">年間売上ダッシュボード</h1>
        <p className="subtitle">1月〜12月の月別売上データを視覚的に確認・管理できます。</p>
      </header>

      <main className="main-content">
        <SalesSummary data={data} />

        <SalesChart data={data} />

        <div className="chart-card">
          <h3 style={{ marginBottom: '1rem', fontSize: '1.25rem', fontWeight: 600 }}>売上データの追加</h3>
          <form onSubmit={handleAddSales} style={{ display: 'flex', gap: '1rem', flexWrap: 'wrap' }}>
            <input
              type="text"
              placeholder="月 (例: 13月)"
              value={newMonth}
              onChange={(e) => setNewMonth(e.target.value)}
              style={{ padding: '0.5rem', borderRadius: '6px', border: '1px solid var(--border-color)', background: 'var(--card-bg)', color: 'var(--text-main)' }}
              required
            />
            <input
              type="number"
              placeholder="売上 (万円)"
              value={newSales}
              onChange={(e) => setNewSales(e.target.value)}
              style={{ padding: '0.5rem', borderRadius: '6px', border: '1px solid var(--border-color)', background: 'var(--card-bg)', color: 'var(--text-main)' }}
              required
            />
            <button type="submit" className="btn btn-primary">追加</button>
          </form>
        </div>

        <div className="table-container">
          <h3 style={{ marginBottom: '1rem', fontSize: '1.25rem', fontWeight: 600 }}>月別売上詳細データ</h3>
          <table className="sales-table">
            <thead>
              <tr>
                <th>月</th>
                <th>売上 (万円)</th>
              </tr>
            </thead>
            <tbody>
              {data.map((item, index) => (
                <tr key={index}>
                  <td>{item.month}</td>
                  <td>{item.sales.toLocaleString()}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </main>
    </div>
  );
}
